-- Open water: the mere that is fog, what is under it, the drowned village, and the House.

space {
  id = "di_fog_lake",
  region = "dithers",
  wonder = true,
  name = "Fogmere",
  description = "The lode goes white, and then there is no lode. The punt slides out onto a lake with no water in it. It is a mile of fog lying in a hollow of the fen, level as milk in a dish, with a clean edge all round where the reeds stop. The punt rides on it. The pole goes down into it and finds something to push on. Above, the sky is perfectly clear. {magic}You are afloat on a cloud that has settled, and the top of it comes to the gunwale, and you could trail your hand in it.{/}",
  palette = { bg = "#0c1012", text = "#d4dadc", dim = "#727c80", accent = "#e8f0f4", border = "#46525a" },
  ambience = {
    fog { color = "#2a3438", speed = 0.25, strength = 0.9 },
    fog { color = "#1c2428", speed = 0.1, strength = 0.6 },
    dust { glyphs = "·˙", color = "#8a989c", rate = 0.2, speed = 0.2 },
  },

  things = {
    { name = "the fog",
      description = "White, thick and cool, with a surface. You can see the surface. It has slow waves in it, a foot high, that take a minute to cross the mere, and where the punt has passed there is a wake that closes without a sound.",
      things = {
        { name = "the edge", description = "All round the mere the fog stops at the reeds as water would, in a line. A moorhen walks down the bank, steps onto it, and sinks to the neck, and goes on walking, with only its head showing and a small V behind it." },
        { name = "a wave", description = "It comes toward the punt across half a mile, very slowly, smooth as a blanket being shaken out. It lifts the bow. It lifts the stern. Seth Quant bends his knees to it, once, without waking any further." },
        { name = "a handful", description = "You scoop some up. It lies in your cupped hands, white, cool, weighing nothing, and overflows between your fingers and falls back with no splash. Your hands are not wet. They are only a little surprised." },
      },
      actions = {
        { "Trail your hand in it", say "It parts round your wrist. It feels like the inside of a pillow case on a cold morning. Something brushes your fingers, quite deliberately, and is gone. You take your hand out and count them." },
        { "Lower the bailer on a string", say "You pay out line. Six feet, ten, twelve, and it touches. You pull it up. The cow's horn is full to the brim with fog, and at the bottom of the fog there is a buttercup, fresh, with dew on it." },
      } },
    { name = "the punter, here",
      icon = "☺",
      description = "Seth Quant poles across Fogmere exactly as he poles across water. The pole goes in, finds bottom, he walks it back. He will not say what the bottom is. He will only say that it is firmer than the black lode and that it has never yet got his pole.",
      actions = {
        { "Ask what is under the fog", say "\"Mere,\" he says. You say there is no water. \"Never said water. Said mere.\" He leans on the pole. \"My dad told me, you don't get out of the boat on Fogmere. I said, why, is it deep? He said no. He said it's not deep at all.\" He looks at you for the first time. \"That's why.\"" },
        { "Step out of the punt", set "di_fog_stepped", fx "wash",
          say "You put a leg over the side. Seth Quant watches with interest and does not stop you. You let go. You sink, slowly, as into a very deep bed, through white, and through white, and then your boots come down on grass. You are standing in a meadow. The fog is a ceiling a yard over your head, and it is glowing. Above you, the bottom of the punt goes by, black, with a pole coming down beside it and lifting again." },
      } },
    { name = "the sky above",
      description = "Blue from edge to edge, with a small hard sun. All the weather of Fogmere is underneath you. Up here it is the finest day of the year, and has been, every day, since a small girl broke a jug.",
      things = {
        { name = "your shadow", description = "It lies on the fog beside the punt, long and blue, with a ring of faint colours round its head like a saint's. Seth Quant's shadow has one too. He says everyone's does, out here. He says it is the only place he knows where the light is that polite." },
      } },
    { name = "things standing out of the fog",
      description = "Here and there, something breaks the surface.",
      things = {
        { name = "the top of a willow", description = "A round green head, like a bush growing on the fog, with a wagtail in it. The rest of the tree is under. You see that it must be a tall one." },
        { name = "a post with a ring", description = "Oak, standing a foot proud, with an iron ring. A mooring post. The rope from it goes straight down. Something is tied up at the bottom." },
        { name = "a scarecrow's hat", description = "Just the hat and the top of a turnip head, with a crow sitting on it. So there is a field. So somebody has sown it." },
        { name = "a chimney", description = "One brick pot, level with the surface, with a thread of blue smoke coming out of it and lying along the fog. Somebody under there is making tea." },
      },
      actions = { { "Call down the chimney", say "You lean over the pot and say hello. There is a pause. A voice comes up, small and cross and perfectly clear: \"Who's that? Mind my soot.\" Seth Quant poles on. \"That's Widow Pym,\" he says. \"She never left.\"" } } },
    { name = "the ducks",
      description = "A dozen mallard, swimming on the fog. They up-end, tails in the air, as ducks do. When they come up again there is clover in their beaks." },
    { name = "the fog bow",
      description = "Opposite the sun, a white arch standing on the mere, broad and pale, with only the faintest edge of red. A rainbow with the colour left out. They get one every clear morning. The fen people call it the Reeve's Eyebrow." },
    { name = "a fisherman",
      icon = "☺",
      description = "In a small flat boat, a hundred yards off, with a rod. He has a line down in the fog. As you watch, it dips. He strikes, and reels, and brings up, wriggling, a mole. He looks at it without surprise, unhooks it and puts it back.",
      actions = { { "Ask what he is after", say "\"Rabbit,\" he calls across. \"But you take what comes.\" He rebaits. The bait is a carrot. \"Had a hare on Tuesday. Fought like a salmon.\"" } } },
    { name = "the sound of it",
      description = "Fog deadens everything. The pole makes no splash. But from underneath, faint, come sounds that have no business under a lake: a cow. A gate. A dog. Somebody beating a carpet." },
    { name = "the middle",
      description = "Half a mile from any shore, where the fog is at its thickest and whitest, there is a dimple in the surface, a yard across, turning slowly. The fog goes down in it as bath water goes down a drain. Seth Quant steers round it at a respectful distance.",
      things = {
        { name = "what goes down", description = "A leaf comes by on the surface, reaches the dimple, circles it twice and is gone. You wait. Some way off, a different leaf comes up." },
      } },
    { name = "a swan",
      description = "White on white. You see the black of its bill and eye first, moving along with nothing behind them, and then the rest of it comes out of the glare like a thought. It regards the punt, hisses on principle, and sails on, with its feet working in the top of a hawthorn." },
    { name = "the tide line",
      description = "On the reeds at the bank, a foot above the fog, a level band of pale dried bloom. The fog has been higher. \"Comes up when she's upset,\" says Seth Quant. \"Goes down when she's had her tea.\" He does not say who, and you find, some days later, that you know." },
    { name = "a boathook on the bottom boards",
      description = "With a note tied to it: {i}For getting them back in.{/} The hook end is polished with use. A fair number of passengers, it seems, have wanted to see for themselves." },
  },

  exits = {
    { to = "di_staithe", label = "By punt: the staithe", description = "Back up the white lode into the brown, and the world with edges." },
    { to = "di_spire", label = "By punt: the spire", description = "North out of the fog by a cut the punter knows, and over deep water to the church." },
    { to = "di_fog_bottom", label = "Over the side",
      description = "Down through the white, to where your boots found grass.",
      requires = flag "di_fog_stepped", hidden = true },
  },
}

space {
  id = "di_fog_bottom",
  region = "dithers",
  secret = true,
  wonder = true,
  name = "Under Fogmere",
  description = "A meadow, a mile wide, with a ceiling. The fog lies a yard above your head, flat and white and lit from the other side, and it gives a light with no shadows in it, like the light inside an egg. Down here the grass is dry. There are buttercups. There are cows, a hedge, a lane, and a cottage with smoke going straight up through the roof of the world. {magic}It is the one piece of the Dithers that made up its mind. It is land, and has been all along, and nobody above can see it.{/}",
  palette = { bg = "#101210", text = "#dcdcd0", dim = "#7c8070", accent = "#e8dc80", border = "#4c5444" },
  ambience = {
    fog { color = "#30362e", speed = 0.2, strength = 0.5 },
    dust { glyphs = "·˙", color = "#a0a070", rate = 0.3, speed = 0.3 },
    fireflies { glyphs = "·", color = "#e8e0a0", rate = 0.15 },
  },

  things = {
    { name = "the ceiling",
      description = "White, even, glowing, and very slightly in motion. It is near enough to touch if you jump. You can see things on the other side of it, as you see leaves on a pond from below.",
      things = {
        { name = "the punt going over", description = "A black shape like a long fish, crossing the sky without a sound. A pole comes down through the white ahead of it, touches the turf beside a cowpat, pushes, and is drawn up again. There is a row of small round dents across the whole meadow. Generations of them." },
        { name = "ducks, from below", description = "Twelve pairs of orange feet, paddling in the air overhead. Now and then a green head comes down through the ceiling on a long neck, takes a mouthful of clover, looks at you upside down, and goes back up." },
        { name = "a hook on a line", description = "It hangs down out of the white with a carrot on it, turning. A rabbit is sitting underneath, looking up, thinking it over. You have a strong wish to see how this comes out and an equally strong feeling that you should not be on either side." },
      },
      actions = { { "Jump and touch it", say "Your fingers go into the white to the knuckle. Cool. And on the far side of it, sunlight: you feel it, warm on your fingertips, for the length of the jump. You land. Up above, a man in a punt has just seen four fingers come out of Fogmere, and will not mention it to anybody." } } },
    { name = "the meadow",
      description = "Old grass, never ploughed, thick with flowers. Because it has had fog over it for sixty years and no frost, no drought and no hard sun, everything is in bloom at once: cowslips with harebells, snowdrops under the dog roses.",
      things = {
        { name = "the buttercups", description = "Knee high and so yellow that they light your chin from where they stand. The whole floor of the mere shines up at its own ceiling, and the ceiling shines back." },
        { name = "a fairy ring", description = "A dark circle in the grass, thirty feet across, with a rim of small pale mushrooms. There is a three-legged stool in the middle. It is where the Widow sits to do her mending, since the light is evenest there." },
        { name = "mole hills", description = "A line of them, fresh. One has a small hole in the top and a fish hook lying beside it, bent straight. Somebody has had a narrow escape and has left the evidence out to make a point." },
      } },
    { name = "the Widow Pym",
      icon = "☺",
      description = "A very old, very small woman in a sunbonnet, coming across the meadow with a milk pail. She was Reeve's wife in Much Wavering before the fog came down. Everyone else took to the boats. She said it was only weather. She has lived under it for sixty years and has not had a wet foot since, which is more than they can say.",
      things = {
        { name = "her sunbonnet", description = "Starched, with a frill. There has been no sun down here in her lifetime. She says it is the principle. She says if you once start going without a bonnet, the next thing is you are a fen person." },
        { name = "her pail", description = "Brim full, and the milk is yellow with cream. Fog-fed cows give the best milk in the kingdom. She makes a cheese a week and sends it up in a basket, on the mooring rope. A penny comes down. She has never asked who." },
      },
      actions = {
        { "Ask why she stayed", say "\"Stayed? I never went.\" She puts down the pail. \"They all run about up there, boots, boats, is it wet, is it dry. Dithering. I said to Pym, the ground's the ground. It's only that you can't see it.\" She looks up at the white. \"He was a good man. He just needed to be able to see a thing to believe in it. Most do.\"" },
        { "Ask if she is lonely", say "\"With that lot going over all day?\" She points up. A punt crosses. \"That's Seth. I knew his father. I bang on the chimney with the poker when he's late.\" She picks up the pail. \"And the fog girl comes down, Tuesdays, after her club, and cries about some book. I give her tea. She's never once thought to ask if I'd like it lifted.\" She smiles. \"I wouldn't.\"" },
      } },
    { name = "the cottage",
      description = "Brick and tile, square, on the ground. It has a front step. After Much Wavering the plain fact of a doorstep with earth on both sides of it is very nearly shocking. The chimney goes up into the ceiling and the smoke with it.",
      things = {
        { name = "the garden", description = "Cabbages in rows, in soil. Beans on sticks. A gooseberry bush. In the Dithers above, a cabbage is brought in by boat and guarded. She has forty." },
        { name = "the mooring rope", description = "It comes down out of the white and is tied to her boot scraper. There is a basket on a hook. Up top, it is the post with the ring. She tugs it twice when the cheese is ready." },
        { name = "a poker by the hearth", description = "Bent, from being reached up the chimney. For Seth." },
        { name = "the clock", description = "A long-case clock in the kitchen, ticking. It is the only clock in the Dithers that has never been wedged level, since the floor it stands on has never moved. The whole fen takes its time from the Loose Mooring, which takes it from a man with a watch who lives up above. His watch, unknown to anyone, was set by this." },
      },
      actions = { { "Stand on the doorstep", say "You stand on it. You step off it onto the path. You step back on. Earth, stone, earth. It stays where you left it each time. You had not known how much of your attention the Dithers had been taking, until something gave it back." } } },
    { name = "the cows",
      description = "Six, red, sleek as seals, lying in the buttercups chewing. They have never been rained on, never been bitten by a fly and never seen a horizon. They have the look of creatures to whom nothing has happened, and who would like that to continue.",
      actions = { { "Sit down by a cow", say "She shifts over. You lean against a flank the size of a sofa and listen to her insides working. Above you, the white goes by. You have been wet, lost, tarred and patronised by a goose. For a quarter of an hour none of it is true." } } },
    { name = "the hedge and the lane",
      description = "A hawthorn hedge, in flower, and beside it a lane with two ruts and a grass middle. It crosses the meadow from one side to the other and goes into the fog bank at each end, where the ceiling comes down to the ground. It is a perfectly good lane. It has been waiting sixty years for a cart.",
      things = {
        { name = "the hawthorn tops", description = "The hedge is a little taller than the ceiling is high. Its upper twigs go into the white. Up there, a swan is paddling through them." },
        { name = "a signpost in the lane", description = "One arm. {b}MUCH WAVERING ½{/}. It points along the lane into the fog. The village was here. This is where it stood when it stood on the ground, before the legs, eleven moves ago." },
        { name = "a gate", description = "Five bars, shut, with a loop of chain. It leads from the lane into the meadow. There is no fence on either side of it. The Widow opens it and closes it behind her every time. She says that is how you can tell a field from just some grass." },
      } },
    { name = "the scarecrow",
      description = "In the bean rows, with its turnip head up through the ceiling and a crow sitting on the part you cannot see. Down here it is a coat on a stick with a pair of gloves. It has frightened nothing in sixty years. No bird comes below the fog but the ducks, and those only as far as the neck." },
    { name = "the willow",
      description = "The trunk of the tall one, going up like a pillar and through. There are steps cut in it. This is how a small pink witch comes down on Tuesdays, sideways, holding her skirts, to be given tea and to be let cry." },
    { name = "the drain",
      description = "In the middle of the meadow the fog comes down in a slow white rope, a yard thick, turning, and goes into a stone well head set in the grass. It pours in steadily and makes no sound. The well has a wooden lid, propped open, and a bucket.",
      things = {
        { name = "the well", description = "You look down. White, going down, and at the bottom a round of blue. It is sky. It is the same sky that is over the fog. The Widow says it has always done that, and that she draws her water from the pump." },
      },
      actions = { { "Drop a buttercup in", say "It goes down the white rope, turning, small and yellow, and is gone into the blue. You wait for a long time. Then it comes down past your shoulder, out of the ceiling, and lands in the grass at your feet. The Widow, passing with her pail, does not even look. \"It only goes round,\" she says." } } },
    { name = "things that fell in",
      description = "Along the hedge, hung up neatly on the thorns: everything that has been dropped over the side of a boat in sixty years. She collects them. A dozen hats. A pipe. Three pairs of spectacles. A set of teeth. A nine-foot duck gun.",
      things = {
        { name = "the duck gun", description = "Brass-bound, with {i}E. MALLOW{/} burnt into the stock. So he did walk on the bottom. And left in a hurry." },
        { name = "the teeth", description = "On a twig, grinning. Barnaby Float's father's. He leaned over to see how deep it was. The Widow says she sent a note up on the rope and nobody came, out of embarrassment." },
        { name = "a row of pole shoes", description = "Iron caps off the ends of punt poles, eleven of them, stuck on a rail like thimbles. Seth's family have been losing those here for a hundred years and writing them off to mud." },
      } },
    { name = "the light",
      description = "It comes from all of the ceiling at once and has no direction. Nothing down here casts a shadow: not the cows, not the hedge, not you. You hold out your hand over the grass and there is nothing under it. It is the most peaceful thing you have ever noticed and you cannot say why." },
    { name = "a lark",
      description = "It goes up singing from the buttercups, as larks do, climbing straight. It reaches the ceiling and vanishes into it, and the song goes on, fainter, from the other side. Up there, in the sun, a man in a boat hears a lark rise out of the lake. He has given up telling people." },
    { name = "the edge of the meadow",
      description = "Where the ground rises, the ceiling comes down to meet it, and you walk up a bank into plain white with your arms out. Ten steps and your head comes through into sunlight and reeds, with a moorhen looking at you. There is a way out all round. There always was." },
  },

  exits = {
    { to = "di_fog_lake", label = "Up the willow steps", description = "Hand over hand up the trunk, through the white, into the top of a tree with a punt waiting alongside and a boathook held out." },
  },
}

space {
  id = "di_spire",
  region = "dithers",
  wonder = true,
  name = "The Spire of Little Wavering",
  description = "The deep lode opens into a wide still lake, and in the middle of it a church spire stands straight up out of the water. Forty feet of grey stone and lead, with a golden cock on top. Round it, under the surface, you can see the roofs: the nave, a street of cottages, an inn sign, an orchard, all standing in clear brown water as in amber, with fish going in at the windows. {magic}This is Little Wavering, which would not go on legs.{/} Much Wavering ties its boats to the spire on Sundays and holds the service from above.",
  palette = { bg = "#080e12", text = "#c4d0d4", dim = "#586a72", accent = "#e0c868", border = "#2a4450" },
  ambience = {
    shimmer { color = "#2a5060", strength = 0.2 },
    fog { color = "#101c22", speed = 0.1, strength = 0.3 },
    dust { glyphs = "·˙", color = "#4a6a74", rate = 0.3, speed = 0.3 },
  },

  things = {
    { name = "the spire",
      description = "Eight-sided, tapering, with small windows at each stage and bands of worn carving. The water comes to the top of the tower it stands on. What you are looking at, from a boat, is what the swifts used to see.",
      things = {
        { name = "the mooring rings", description = "Iron, let into the stone at water level by the people of Much Wavering. There are grooves below them, and more rings, green, a foot under, and another row a yard down. The water has come up since they started mooring here. They have followed it up the steeple." },
        { name = "a spire light", description = "A small window, level with your shoulder. Inside is the bell chamber, dry, with the frame and the wheels and four bells hanging mouth down an arm's length above the water. The ropes go down into it. A coot is nesting on the treble." },
        { name = "the carving", description = "A band of stone faces round the spire, meant to be seen from the ground a long way below. Up close they are rough, big-nosed and cheerful. The mason never thought anyone would get this near. One of them is putting its tongue out." },
        { name = "names cut in the lead", description = "Just above the waterline: every couple married at the spire since the flood, scratched with a boathook from the bows. The bride's punt and the groom's are lashed together for the vows. If they are still level by the amen, it is thought a good sign." },
      },
      actions = {
        { "Tie up to it", say "Seth Quant drops a loop over a ring. The punt swings and lies against the stone. You put your hand on a church steeple, from a seat, at about the height where the bell ringer's grandfather used to say you could see three counties. You can see one. It is all the Dithers." },
        { "Pull a bell rope", say "You reach in through the light and take hold of a rope. It is wet for most of its length. You pull. Above your hand, the tenor swings and speaks, one clear note out over the water. And under you, a moment later, you feel it in the boards of the punt: the same note, coming up from the nave, slower, having gone round the church the long way." },
      } },
    { name = "the weathercock",
      description = "Gilded copper, a yard long, on an iron rod at the very top. It is the only weathercock in the kingdom that is regularly polished, since a boy can reach it by standing on a punt seat. It points into the wind, which today is from the west, and smells of salt.",
      things = {
        { name = "the dent", description = "In its side, the size of a hand. Barnaby Float's inn, one morning. Both parties still speak of it." },
      },
      actions = { { "Spin it", say "You give the tail a push. It goes round twice, squealing, and comes back to the west exactly, with a small click, and stays. You have the impression of having interrupted an official at his desk." } } },
    { name = "the drowned village",
      description = "You lean over the side. The water is as clear as the Dithers gets: brown glass, lit from above. Twenty feet down there is a street.",
      things = {
        { name = "the church roof", description = "Lead and stone slate, straight below the punt, with the ridge running east. Weed grows along it like grass on a wall. A shoal of rudd turns over the nave, all together, and for a moment every one of them is the gold of the weathercock." },
        { name = "the street", description = "Cobbled, with a gutter down the middle. Cottages on both sides, their thatch long gone and the rafters standing like ribs. Every door is shut. They shut them when they left. A village that would not go on legs was still not going to leave its doors open." },
        { name = "the inn sign", description = "Standing up from a wall on its bracket, swinging in the current as it once did in the wind. The paint is gone. The fen people say it was called the Dry Foot. They do not say it unkindly." },
        { name = "the orchard", description = "Behind the church: a square of trees, black and bare, still in their rows. In May, somebody says, they blossom. Under the water. White, for a week. You are told this by a man who then looks away, as you do when you have said a true thing that sounds like a lie." },
        { name = "a light in a window", description = "At the far end of the street, in an upstairs room: a small steady glow, yellow, not blue. You watch it. It does not move as a fish moves. Seth Quant sees where you are looking and takes the punt round to the other side of the spire." },
      },
      actions = {
        { "Drop a penny", say "You let the bent copper slip, then catch it against the gunwale: that one has a gate to pay. You find a button instead. It goes down turning, and winks, and lands on a doorstep. A crayfish comes out from under the door, looks at it, and takes it inside." },
      } },
    { name = "the Sunday boats",
      description = "Posts stand in a ring round the spire, a punt's length off, each with a family's mark. On Sundays there are thirty boats here, bows in, like the petals of a daisy, and the parson in the middle with one foot on the stone.",
      things = {
        { name = "the parson's punt", description = "Kept here all week, tied to the spire, with a reading desk nailed across the thwarts and a cushion to kneel on. There is a sounding line in it. He takes the depth of the nave before every sermon, and gives it out with the hymn numbers." },
        { name = "the Pym post", description = "The best place, due west, facing the door they cannot see. Carved with forty notches." },
        { name = "an empty post", description = "No mark. It has always been kept, on the north side, for anyone from Little Wavering who cares to come up. A rope end is tied to it, fresh every year. It hangs down into the water. On some Mondays, the parson says, it has been found taut." },
      } },
    { name = "the churchyard wall",
      key = "di_churchyard",
      description = "East of the spire the ground is higher and the top of a stone wall is just awash: a line of coping stones a hand under the surface, running round a square of deeper water. Inside the square, the tops of headstones show like stepping stones, with a wagtail on each.",
      things = {
        { name = "the nearest headstone", description = "The top six inches, green. {i}Here lies{/}, it says, and the rest is under. You lean out. {i}Here lies ABEL PYM who said it would go down again.{/}" },
        { name = "the yew", description = "Dead, grey, standing in the water with its arms up. Cormorants sit in it with their wings held open to dry, like a row of broken umbrellas. It was a thousand years old when the water came. It has not fallen. Yew does not see why it should." },
      } },
    { name = "the frog on the wall",
      key = "di_wall_frog",
      icon = "f",
      description = "On the coping of the churchyard wall, upright, with a rolled dock leaf under its arm: the frog from the staithe, or its twin. It has been waiting for the punt. It looks at you, and at a low stone arch across the water where the market place used to be, and back at you, with the patience of an usher.",
      variants = {
        { when = flag "di_frogs_found", description = "The clerk's place on the wall is empty. There is a wet mark where he sat, and one dock leaf, dropped, with small neat marks all over it in rows. You cannot read frog. You suspect it is minutes." },
      },
      actions = {
        { "Follow the frog", when = no(flag "di_frogs_found"), set "di_frogs_found",
          say "It goes in off the wall with a small official plop and swims, kicking like a man in a hurry, to the arch. There it climbs out on a ledge and looks back. Seth Quant puts the pole in without being asked. Under the arch there is a roofless hall, flooded to the window sills and floored from wall to wall with lily pads. Every pad has a frog on it. They are all facing the same way. The one with the leaf takes his place below a large pad at the far end, opens the leaf, and croaks, once. The noise stops like a door shutting. You are, you gather, in the gallery." },
      } },
    { name = "the deep water",
      description = "Round the spire it is thirty feet, and the pole only just finds it. The bottom here is the village green. Seth Quant plants the shoe of his quant between a pump and a horse trough without looking.",
      things = {
        { name = "a big fish", description = "Something long and dark comes out of the church porch, turns down the street, and goes in at the door of what was the baker's. The door was shut. You look again. It is shut." },
      } },
    { name = "swallows",
      description = "A dozen, hawking low over the water round the spire, turning on a wingtip. They still nest in the bell chamber. Their grandparents came in at the louvres from a sky. These come in from a lake. They have not altered the route by a yard." },
    { name = "the flood stone",
      description = "A slab set into the spire, just above the water. {i}THE WATERS CAME UP ON SAINT WOBBLE'S EVE. WE HAD BEEN TOLD. LET IT BE SAID OF LITTLE WAVERING THAT IT STOOD ITS GROUND.{/} Below that, in a different hand, later, scratched from a boat: {i}it did, bless it{/}." },
    { name = "the quiet of the place",
      description = "Open water, a wide sky, one upright thing. People from Much Wavering lower their voices here without meaning to. They are not sad. A man does not shout in his grandmother's parlour, that is all, even when she is out." },
    { name = "a cormorant",
      description = "On the tip of the empty post, black, greasy, with a hooked beak and a green eye. It dives off, goes down the street at roof height, turns in at the churchyard gate and comes up with an eel. It is the only parishioner who still uses the gate." },
    { name = "a sermon board",
      description = "Hung on the spire by two hooks, a foot above the water, painted fresh each week. {i}THIS SUNDAY: Consider the lilies. Depth of nave: 21 ft 4 in. Bring a cushion.{/}" },
  },

  exits = {
    { to = "di_staithe", label = "By punt: the staithe", description = "South down the deep lode, with the spire going small behind you." },
    { to = "di_fog_lake", label = "By punt: Fogmere", description = "By the cut the punter knows, out of the clear and into the white." },
    { to = "di_frogs", label = "Under the market arch",
      description = "Through the low stone arch to the flooded hall, quietly, hat off.",
      requires = flag "di_frogs_found", hidden = true },
  },
}

space {
  id = "di_frogs",
  region = "dithers",
  secret = true,
  name = "The Lower House",
  description = "The moot hall of Little Wavering has lost its roof and kept its walls. Inside, the water lies still and green between them, covered with lily pads in two blocks with a clear lane down the middle. On every pad sits a frog. There are four hundred. At the far end, on a pad twice the size, under what was once the magistrates' window, sits a very large frog indeed, with its eyes shut. This is the Parliament of Frogs. It has sat here since the hall flooded, and somewhere else before that, and it was old when men first argued. It is debating the Heron Question. It has always been debating the Heron Question.",
  palette = { bg = "#08100a", text = "#c8d4c0", dim = "#5e7058", accent = "#a0d870", border = "#2e4a2c" },
  ambience = {
    drip { glyphs = "·˙", color = "#5a9060", rate = 0.3 },
    shimmer { color = "#2a5030", strength = 0.15 },
    fireflies { glyphs = "·", color = "#c0e890", rate = 0.2 },
  },

  things = {
    { name = "the House in session",
      wonder = true,
      description = "A member on the left croaks, at length. Four hundred throats swell and go down. Then the right block answers, all together, one deep note, and the left replies, one higher, and it goes back and forth across the lane of water like a tide in a very small sea. {magic}It is the frog chorus you have heard from every ditch since you were born, and you understand for the first time that it was never a song. It is a division.{/} They have been voting, all over the world, every spring night, for as long as there have been ponds.",
      things = {
        { name = "the Ayes", description = "On the left as you look: the reed frogs, green, slim, inclined to enthusiasm. They sit forward on their pads. When one of their own speaks they go {i}rrrp{/} in a rising tone, which is {i}hear, hear{/}." },
        { name = "the Noes", description = "On the right: the old brown frogs of the peat, broad and warty and slow to blink. They say {i}grawk{/}, falling, which is {i}shame{/}. They say it to everything, on the sound principle that most things are." },
        { name = "the cross benches", description = "Three toads on a floating plank at the back, belonging to neither side. They have not spoken in the memory of the House. Both sides claim that this is agreement." },
      },
      actions = {
        { "Listen to the debate", say "You sit very still. After a while the noise sorts itself. The Member for Lesser Puddle is saying that herons are a matter for each pond. The Member for the Black Lode is saying that a heron does not respect pond boundaries. Somebody at the back says what about pike, and is told that pike are not on the paper. It is all perfectly clear. It is exactly like the Council of Aldmoor, only shorter in the leg and more to the point." },
      } },
    { name = "the Speaker",
      icon = "♔",
      description = "The largest frog you have ever seen, the size of a soup plate, olive and gold, motionless on the great pad. Its eyes are shut. It has been Speaker for eleven years, which is four lifetimes. It appears to be asleep. Then a member on the left says something a shade too far, and one eye opens, the colour of a brass button, and the whole House goes down flat on its lilies.",
      actions = {
        { "Catch the Speaker's eye", say "You do not mean to. It simply opens, and you are in it. There is a pause in which four hundred frogs turn round. The Speaker's throat swells, slowly, to the size of an apple, and lets out one note, low and long. The clerk writes. You learn later that the Stranger in the Gallery was recognised, and thanked for his attendance, and asked not to drip." },
        { "Ask about the mace", when = no(item "di_frog_mace"), give "di_frog_mace",
          say "You look at the bulrush on the lily before the Speaker's pad, and then at the other one, the old one, gilt worn to the stalk, lying on a ledge under the window with a spider's web on it. You say nothing aloud. The Speaker's eye follows yours. One note. A division: the left block, the right block, the left again. It is the shortest debate of the session. The Serjeant, a lean frog with a very straight back, swims to the ledge, takes the old mace in both arms like a man carrying a ladder, and brings it across the hall to the punt. He lays it on the gunwale and bows. The House has voted it to you, nem con, the toads abstaining. You gather it is because you took your hat off." },
      } },
    { name = "the mace on the lily",
      description = "A bulrush, new this year, lying across a small pad of its own in front of the Speaker. While it lies there the House is sitting, and what is croaked is law in every ditch from the wood to the sea. At sunrise the Serjeant removes it, and they are four hundred frogs in a ruin." },
    { name = "the clerk",
      icon = "f",
      description = "Your acquaintance with the dock leaf, at a flat stone below the Speaker, writing with a wet foot. He writes down every word. A dock leaf lasts one sitting. The archive, therefore, is compost, and extremely fertile, and the marsh marigolds along the east wall are the best in the fen.",
      things = {
        { name = "today's leaf", description = "Rows of small damp prints, already drying. He works fast. You see him stop, consider, and delete a remark by licking it off." },
        { name = "the order paper", description = "A water-lily petal, floating by his stone. Item one: {i}the Heron Question{/}. Item two: {i}the Heron Question, resumed{/}. Item three: {i}any other herons{/}." },
      } },
    { name = "the statute wall",
      description = "The north wall of the hall, from the waterline to as high as a frog can jump, is green with a fine moss. In the moss, pressed with small feet, are the Acts of the House. Each spring's law is trodden in below the last. The lowest are under water, and under silt, and go down to the hall's foundations and, they hold, some way past.",
      things = {
        { name = "this year's Act", description = "Fresh, bright, at eye level for a frog. A member of the Ayes translates it for you by sitting next to each mark in turn and looking meaningful. It provides that a heron shall give notice." },
        { name = "an old Act, much worn", description = "It establishes that a pond is a pond when it has been wet two springs running. Everything in the Dithers, you realise, rests on this. It is the only definition anybody in the fen has ever managed." },
        { name = "the first Act", description = "They cannot show you, it is too deep. But they have it by heart and the whole House croaks it together at the opening of every session, standing. The clerk gives you the sense of it. {whisper}An Act to Continue: it having been found, on the first day of sitting, that things were already going on.{/}" },
      },
      actions = { { "Touch the moss", say "Four hundred frogs draw breath. You take your finger away. You have, it appears, very nearly amended something." } } },
    { name = "the Member for Lesser Puddle",
      icon = "f",
      description = "A small green frog, on a pad in the front row of the Ayes, speaking. It has been speaking since you came in. It represents a hoof print by the causeway that fills when it rains, and it speaks for that hoof print with a passion that would do credit to the Member for an ocean.",
      actions = { { "Nod along", say "It sees you nod. It turns toward the gallery and gives you the next ten minutes directly, with gestures. You understand none of it. At the end you find you are in favour, strongly, and would like to know of what." } } },
    { name = "the Father of the House",
      description = "A brown frog on the Noes' side, so old that it has gone the grey of a stone, with moss on its back. It was a tadpole in the year of the big flood. It has said {i}grawk{/} to every measure for seven springs and is held in great affection by the members it has voted against, which is all of them." },
    { name = "the Serjeant",
      description = "A lean, long-legged frog on a ledge by the arch, facing outward. He keeps the door. Twice in a sitting he makes the round of the walls, swimming on his back so as to watch the sky. If he croaks three times, short, the whole House is under its lilies before the third. That is the only Standing Order, and it concerns standing.",
      things = {
        { name = "the sky over the hall", description = "A square of it, where the roof was. It is empty. The Serjeant watches it without blinking. There is a grey shape that goes over the Dithers twice a day on wide slow wings, and the entire constitution of the frogs is built round the hours it keeps." },
      } },
    { name = "the lily pads",
      description = "Each one a seat, held by a family, handed down. A member who is absent leaves a water snail on the pad to keep it. There are, today, eleven snails, and they are counted as present for the purposes of a quorum and have, on occasion, carried a vote.",
      things = {
        { name = "an empty pad with a flower on it", description = "One lily, white, open, on a pad in the front row with no frog. Nobody sits there. The clerk, when you look at him, makes the shape of a long beak with two fingers, and then looks at the water." },
        { name = "the smallest pad", description = "A leaf of frogbit no bigger than a penny, at the back, with a froglet on it that still has a stump of tail. The Member for the Newly Arrived. It is very quiet and very upright and has clearly been told this is a great honour." },
      } },
    { name = "the old mace on its ledge",
      key = "di_old_mace",
      description = "Under the magistrates' window, on a sill just above the water: a second bulrush, gilded, the gold worn off the stem, with a spider's web from its head to the wall. It was the mace when this hall had a roof. It was the mace before that, in a pool where the church now stands. They retired it, with honours, and have not known what one does next with a thing like that.",
      variants = {
        { when = item "di_frog_mace", name = "the ledge under the window", description = "A sill just above the water, with a long clean mark in the dust where the old mace lay. The spider is still there. It has started a new web, from the wall to nothing in particular, on the assumption that something will be put back." },
      } },
    { name = "the magistrates' bench",
      description = "The stone seat of the old moot, along the end wall, with the royal arms carved over it. The water is a foot over the seat. A row of tadpoles hangs there in the warm shallows, small black commas, under the arms of a King they have never heard of. They are the schools." },
    { name = "the gallery",
      description = "Which is to say the punt, under the arch, and you in it, and Seth Quant standing behind you with his hat off. He has brought people here before, you understand: not many. He says the frogs were good to his father in a hard year. He does not say how. You try to think how frogs could be good to a punter and you find that you believe it." },
    { name = "the walls",
      description = "Stone, roofless, with ferns in every joint and an elder growing out of the gable. On the inside, a line of brackets where the beams went. A wren has a nest on one. She sings straight through the debate, very loud, and the House has ruled, after a famous sitting, that she is in order." },
    { name = "the sound, afterwards",
      description = "You will hear it again, from a ditch, on some spring night a long way from here. One side, and then the other. And you will know that a motion is being put, and stop, and take your hat off in the dark, and somebody with you will ask what on earth you are doing." },
  },

  exits = {
    { to = "di_spire", label = "Out under the arch", description = "Backing the punt out, quietly, so as not to leave during a speech." },
  },
}
